try {
  const payload = $json || {};
  const isCallback = !!payload.callback_query;
  const msg = isCallback ? (payload.callback_query.message || {}) : (payload.message || {});
  const from = isCallback ? (payload.callback_query.from || {}) : (payload.message?.from || {});
  const texto = isCallback ? (payload.callback_query.data || '') : (payload.message?.text || '');

  return [{
    json: {
      eventType: isCallback ? 'callback_query' : 'message',
      callbackQueryId: isCallback ? String(payload.callback_query.id || '') : '',
      callbackData: isCallback ? String(payload.callback_query.data || '') : '',
      chatId: String(msg.chat?.id || ''),
      userId: String(from.id || ''),
      responsavel: `${from.first_name || ''} ${from.last_name || ''}`.trim() || from.username || String(from.id || ''),
      texto_original: String(texto).trim(),
      texto_normalizado: String(texto).trim().toLowerCase(),
      dataHoje: new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
      nowTs: Date.now()
    }
  }];
} catch (error) {
  return [{ json: { eventType: 'erro', erro: `Falha no contexto: ${error.message}` } }];
}

try {
  const store = typeof $getWorkflowStaticData === 'function' ? $getWorkflowStaticData('global') : this.getWorkflowStaticData('global');
  if (!store.sessions) store.sessions = {};

  const uid = String($json.userId || '');
  const sessao = store.sessions[uid] || { modo: 'ia' };

  return [{ json: { ...$json, modo: sessao.modo || 'ia' } }];
} catch (error) {
