}

try {
  const ctx = ($items("Code ContextoEvento")[0] || {}).json || {};
  const texto = String(ctx.texto_normalizado || "").toLowerCase().trim();

  const termo = texto
    .replace(/^consultar\s+/, "")
    .replace(/^consulta\s+/, "")
    .trim();

  const rows = $input.all().map(i => i.json);

  if (!termo) {
    return [{ json: { mensagem: "Informe o produto para consulta. Exemplo: PROD-001" } }];
  }

  const getField = (obj, keys, fallback = "") => {
    for (const k of keys) {
      if (obj[k] !== undefined && obj[k] !== null && String(obj[k]).trim() !== "") {
        return String(obj[k]).trim();
      }
    }
    return fallback;
  };

  const found = rows.filter(r => {
    const nome = getField(r, ["Nome_Produto", "Nome", "nome_produto", "nome"]).toLowerCase();
    const id = getField(r, ["ID_Produto", "ID", "id_produto", "id"]).toLowerCase();
    return nome.includes(termo) || id.includes(termo);
  });

  if (!found.length) {
    return [{ json: { mensagem: `Nenhum item encontrado para "${termo}".` } }];
  }

  const f = found[0];

  const nome = getField(f, ["Nome_Produto", "Nome"], "-");
  const id = getField(f, ["ID_Produto", "ID"], "-");
  const quantidade = getField(f, ["Quantidade_Atual", "QuantidadeAtual", "Quantidade", "Qtd"], "0");

  let status = getField(f, ["Status"], "");
  // Se Status vier numÃ©rico (ex.: 80), calcula status textual automaticamente
  if (!status || !Number.isNaN(Number(status))) {
    status = Number(String(quantidade).replace(",", ".")) > 0 ? "DisponÃ­vel" : "Sem estoque";
  }

  const msg = [
    "Estoque Atual",
    "",
    `Produto: ${nome}`,
    `ID: ${id}`,
    `Quantidade Atual: ${quantidade}`,
    `Status: ${status}`
  ].join("\n");

  return [{ json: { mensagem: msg } }];
} catch (error) {
  return [{ json: { mensagem: `Erro na consulta: ${error.message}` } }];
}

try {
  const texto = ($json.texto_original || '').trim();
  const partes = texto.split(',').map(v => v.trim());

  if (partes.length < 3) {
    return [{ json: { ...$json, status: 'erro', motivo: 'Formato invÃƒÂ¡lido. Use: PROD-001, 5, 25.00' } }];
  }

  const idProduto = (partes[0] || '').toUpperCase();
  const quantidade = Number(String(partes[1]).replace(',', '.'));
  const preco = Number(String(partes[2]).replace(',', '.'));
  const tipoRaw = (partes[3] || 'Entrada').toLowerCase();
  const tipo = tipoRaw.startsWith('s') ? 'SaÃƒÂ­da' : 'Entrada';

  if (!/^PROD-\d{3,}$/i.test(idProduto)) {
    return [{ json: { ...$json, status: 'erro', motivo: 'ID_Produto invÃƒÂ¡lido. Exemplo: PROD-001' } }];
  }
  if (!Number.isFinite(quantidade) || quantidade <= 0) {
    return [{ json: { ...$json, status: 'erro', motivo: 'Quantidade invÃƒÂ¡lida.' } }];
  }
  if (!Number.isFinite(preco) || preco < 0) {
    return [{ json: { ...$json, status: 'erro', motivo: 'PreÃƒÂ§o invÃƒÂ¡lido.' } }];
  }

  return [{
    json: {
      ...$json,
      status: 'ok',
      ID_Produto: idProduto,
      Tipo: tipo,
      Quantidade: String(quantidade),
      Preco: preco.toFixed(2),
      Data: $json.dataHoje
    }
  }];
} catch (error) {
  return [{ json: { ...$json, status: 'erro', motivo: `Erro no parse padronizado: ${error.message}` } }];
}

