try {
  const rawText = Object.values($json || {}).map(v => String(v ?? '')).join('\n');
  const cleaned = rawText.replace(/```json|```/gi, '');
  const blocks = cleaned.match(/\{[\s\S]*?\}/g) || [];
  let best = null;
  for (const b of blocks) {
    try {
      const j = JSON.parse(b);
      if (!best || String(j.status || '').toLowerCase() === 'ok') best = j;
    } catch (e) {}
  }
  if (!best) best = { status: 'erro' };

  const ctx = $items('Code ContextoEvento')[0]?.json || {};
  const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  const tipoRaw = String(best.Tipo || '').toLowerCase();
  const tipo = tipoRaw ? (tipoRaw.startsWith('s') ? 'SaÃ­da' : 'Entrada') : '';
  const qtd = Number(String(best.Quantidade || '').replace(',', '.'));
  const preco = Number(String(best.Preco || '').replace(',', '.'));
  const data = /^\d{2}\/\d{2}\/\d{4}$/.test(String(best.Data || '')) ? String(best.Data) : hoje;
  const id = String(best.ID_Produto || '').toUpperCase().trim();

  const ok =
    String(best.status || '').toLowerCase() === 'ok' &&
    /^PROD-\d{3,}$/i.test(id) &&
    (tipo === 'Entrada' || tipo === 'SaÃ­da') &&
    Number.isFinite(qtd) && qtd > 0 &&
    Number.isFinite(preco) && preco >= 0;

  return [{
    json: {
      eventType: ctx.eventType || '',
      callbackQueryId: ctx.callbackQueryId || '',
      callbackData: ctx.callbackData || '',
      chatId: ctx.chatId || '',
      userId: ctx.userId || '',
      responsavel: ctx.responsavel || '',
      texto_original: ctx.texto_original || '',
      texto_normalizado: ctx.texto_normalizado || '',
      dataHoje: ctx.dataHoje || hoje,
      nowTs: ctx.nowTs || Date.now(),
      status: ok ? 'ok' : 'erro',
      motivo: ok ? '' : 'NÃ£o foi possÃ­vel validar resposta da IA.',
      ID_Produto: id,
      Tipo: tipo,
      Quantidade: Number.isFinite(qtd) ? String(qtd) : '',
      Preco: Number.isFinite(preco) ? preco.toFixed(2) : '',
      Data: data
    }
  }];
} catch (error) {
  const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  return [{ json: { status: 'erro', motivo: 'Erro no parse IA: ' + error.message, ID_Produto: '', Tipo: '', Quantidade: '', Preco: '', Data: hoje } }];
}

