try {
  // Remove "=" no comeÃ§o caso venha de expressÃ£o mal formatada
  const raw = String($json.callbackData || '')
    .trim()
    .replace(/^=+/, '');

  // Divide apenas no primeiro ":" para preservar token inteiro
  const idx = raw.indexOf(':');
  const action = idx >= 0 ? raw.slice(0, idx) : raw;
  const token = idx >= 0 ? raw.slice(idx + 1) : '';

  return [{
    json: {
      ...$json,
      callbackRaw: raw,
      callbackAction: action || '',
      callbackToken: token || ''
    }
  }];
} catch (error) {
  return [{
    json: {
      ...$json,
      callbackRaw: '',
      callbackAction: '',
      callbackToken: '',
      erro: error.message
    }
