try {
  const store = typeof $getWorkflowStaticData === 'function'
    ? $getWorkflowStaticData('global')
    : this.getWorkflowStaticData('global');
  if (!store.pending) store.pending = {};

  const action = String($json.callbackAction || '').trim();
  const token = String($json.callbackToken || '').trim().replace(/^=+/, '');

  let pend = store.pending[token];

  if (!pend) {
    const all = Object.values(store.pending);
    pend = all
      .filter(p =>
        p &&
        !p.used &&
        String(p.chatId) === String($json.chatId) &&
        String(p.userId) === String($json.userId)
      )
      .sort((a, b) => Number(b.expiresAt || 0) - Number(a.expiresAt || 0))[0];
  }

  if (!pend) return [{ json: { ...$json, ok: false, motivo: 'PendÃªncia nÃ£o encontrada.' } }];
  if (pend.used) return [{ json: { ...$json, ok: false, motivo: 'Esta confirmaÃ§Ã£o jÃ¡ foi utilizada.' } }];
  if (Number(pend.expiresAt || 0) < Date.now()) return [{ json: { ...$json, ok: false, motivo: 'ConfirmaÃ§Ã£o expirada. Envie novamente a movimentaÃ§Ã£o.' } }];
  if (String(pend.userId) !== String($json.userId) || String(pend.chatId) !== String($json.chatId)) {
    return [{ json: { ...$json, ok: false, motivo: 'UsuÃ¡rio/chat invÃ¡lido para esta confirmaÃ§Ã£o.' } }];
  }

  return [{ json: { ...$json, ok: true, action, pending: pend } }];
} catch (error) {
  return [{ json: { ...$json, ok: false, motivo: 'Erro na validaÃ§Ã£o da pendÃªncia: ' + error.message } }];
}

